/**
 * A geometria e o gesto de um livro de capa dura, fora do componente.
 *
 * Mora separado porque é a parte TESTÁVEL: um livro que muda de espessura entre
 * renders quebra a prateleira, e "a inclinação parece errada" não é coisa que se
 * audita olhando JSX de cena 3D.
 *
 * Nada de `Math.random`, nada de `Date`: dimensão sai da contagem de páginas,
 * inclinação sai do ponteiro. Zero cor — a cor vive em `book-material`.
 *
 * Unidade de mundo: ALTURA DO LIVRO = 1. Toda medida daqui é relativa a ela,
 * então trocar a escala da cena é mexer em um número só, na câmera.
 */

/* ── Geometria ──────────────────────────────────────────────────────────── */

/** Proporção de livro comercial (≈ 6×9 pol). Não é escolha estética: é o que o
 *  olho reconhece como livro em vez de caderno ou catálogo. */
export const RATIO = 0.68;

/**
 * Espessura por página, em altura-relativo. Um livro de 229 mm com 300 páginas
 * de offset dá ~16 mm de miolo; 0.00026 × 300 × 229 mm ≈ 18 mm, contando capa.
 */
const PAPER_PER_PAGE = 0.00026;

/** Piso e teto. Sem eles, um e-book de 40 páginas vira panfleto e um curso de
 *  900 vira tijolo — e os dois leem como defeito, não como informação. */
const MIN_THICKNESS = 0.05;
const MAX_THICKNESS = 0.17;

/** Sem contagem de páginas, este é o livro "de estante" médio. */
const DEFAULT_PAGES = 240;

/** Cartão da capa dura. É ele que cria o degrau na borda — ver `SQUARE`. */
export const BOARD = 0.007;

/**
 * A "praça": o quanto a capa avança além do miolo nas três bordas livres.
 *
 * É o detalhe que separa livro de caixa texturizada. Numa capa dura real o
 * cartão sobra ~3 mm além do bloco de páginas, e é essa sombra fina em volta do
 * corte que o olho lê como "isso abre". Sem ela, qualquer render vira
 * paralelepípedo com uma foto colada.
 */
export const SQUARE = 0.014;

export type BookDimensions = {
  /** Eixo X. Lombada em `-width/2`, corte em `+width/2`. */
  width: number;
  /** Eixo Y. Sempre 1 — é a unidade. */
  height: number;
  /** Eixo Z. Capa em `+thickness/2`. */
  thickness: number;
  /** Espessura só do bloco de páginas, já descontados os dois cartões. */
  block: number;
};

export function thicknessFor(pages?: number | null): number {
  const p = pages && pages > 0 ? pages : DEFAULT_PAGES;
  return Math.min(MAX_THICKNESS, Math.max(MIN_THICKNESS, p * PAPER_PER_PAGE));
}

export function bookDimensions(pages?: number | null): BookDimensions {
  const thickness = thicknessFor(pages);
  return { width: RATIO, height: 1, thickness, block: thickness - BOARD * 2 };
}

/* ── Inclinação ─────────────────────────────────────────────────────────── */

/**
 * Repouso: três-quartos, lombada à vista.
 *
 * Livro de frente é a capa achatada — é a imagem 2D que já existe, e pagar
 * WebGL pra chegar nela seria peso sem receita. O ângulo existe pra mostrar a
 * ÚNICA coisa que a versão 2D não mostra: que o objeto tem lado.
 *
 * `y` positivo gira a lombada (que fica em −X) na direção do observador.
 */
export const REST_Y = 0.38;

/**
 * Inclinação de repouso no eixo X — quem revela a CABEÇA do miolo.
 *
 * ┌─ O SINAL, QUE JÁ FOI ERRADO DUAS VEZES ───────────────────────────────────┐
 * │ Uma face só é visível se o olho estiver do lado de fora do plano dela:    │
 * │ `n · (olho − p) > 0`. Pra tampa de cima, com a câmera abaixo do topo do   │
 * │ livro (y=0.5), isso dá NEGATIVO — não se vê a cabeça de jeito nenhum,     │
 * │ incline-se o livro pra onde for.                                          │
 * │                                                                            │
 * │ E `x` negativo, que parece "baixar o topo", faz o contrário do que o nome │
 * │ sugere: joga a normal do topo pra −z, ou seja, pra LONGE de quem olha.    │
 * │                                                                            │
 * │ Quem resolve é a CÂMERA subir acima de y=0.5. Com ela lá em cima, um `x`  │
 * │ levemente POSITIVO inclina o topo na direção do olho e abre a cabeça — é  │
 * │ o gesto de tombar uma caixa pra ver a tampa.                              │
 * └────────────────────────────────────────────────────────────────────────────┘
 *
 * 0.06 é pouco de propósito: acima disso o livro lê como tombando pra frente.
 */
export const REST_X = 0.06;

/** Curso do hover, em radianos. Teto de propósito: passar disto mostra a
 *  contracapa, que é a face mais fraca do modelo (não tem arte, só tom). */
const SWING_Y = 0.34;
const SWING_X = 0.18;

export type Tilt = { rx: number; ry: number };

export const REST: Tilt = { rx: REST_X, ry: REST_Y };

/**
 * Ponteiro normalizado (−1..1, origem no centro da peça) → rotação do grupo.
 *
 * `px` INVERTE: cursor à direita puxa a lombada pra fora, como se o dedo
 * girasse o livro pelo corte. O contrário — cursor à direita, lombada some — lê
 * como o objeto FUGINDO do cursor, e foi o primeiro descarte da bancada.
 *
 * `py` não inverte, e é o mesmo gesto: cursor na base empurra o pé e o topo vem
 * na direção do olho, mostrando mais cabeça. O objeto obedece ao dedo nos dois
 * eixos.
 */
export function tilt(px: number, py: number): Tilt {
  const cx = Math.max(-1, Math.min(1, px));
  const cy = Math.max(-1, Math.min(1, py));
  return { ry: REST_Y - cx * SWING_Y, rx: REST_X + cy * SWING_X };
}

/**
 * Amortecimento independente de taxa de quadros.
 *
 * `atual + (alvo − atual) * k` — o lerp que todo mundo escreve — depende do
 * intervalo entre quadros: a 144 Hz o objeto chega quase instantâneo e a 30 Hz
 * arrasta. Duas máquinas, duas animações diferentes. A exponencial mata isso:
 * `k` vira "quanto da distância por SEGUNDO", e o resultado é o mesmo em
 * qualquer monitor.
 *
 * O teto de `dt` existe porque aba em segundo plano devolve um delta gigante no
 * primeiro quadro de volta. Sem ele o livro TELEPORTA, e teleporte lê como
 * falha de render.
 */
export function damp(current: number, target: number, k: number, dt: number): number {
  return current + (target - current) * (1 - Math.exp(-k * Math.min(dt, 0.1)));
}

/** Rigidez do retorno. Rápido o bastante pra parecer resposta, lento o bastante
 *  pra ter peso — livro não é botão. */
export const STIFFNESS = 7;

/**
 * Câmera de foto de produto.
 *
 * `fov` longo (24) porque grande-angular deforma a capa e denuncia o render —
 * 24 mm equivalente é onde foto de produto vive. A ALTURA não é gosto: o topo
 * do livro está em y=0.5 e uma face só aparece pra quem está fora do plano
 * dela, então abaixo de 0.5 a cabeça do miolo não aparece em ângulo nenhum e a
 * praça — metade da razão de a malha ter quatro peças — nunca chega à tela.
 */
export const CAMERA = { position: [0, 0.55, 2.9] as const, fov: 24 };

/**
 * A matéria do livro, derivada dos tokens da marca.
 *
 * ┌─ WEBGL NÃO LÊ CSS ────────────────────────────────────────────────────────┐
 * │ A tese da library é "componente nunca tem cor própria: ele consome        │
 * │ `var(--brand)`". Um material do three.js não pode fazer isso — não há     │
 * │ cascata dentro de uma cena WebGL, e `var(--card)` não significa nada pra  │
 * │ um `MeshStandardMaterial`.                                                │
 * │                                                                            │
 * │ A saída não é abrir exceção e escrever hex: é usar o PRÓPRIO NAVEGADOR    │
 * │ como resolvedor. Escreve-se a expressão de token num elemento             │
 * │ descartável, lê-se o `getComputedStyle` de volta, e o que chega é o rgb   │
 * │ exato que o CSS pintaria — inclusive através de `color-mix(in oklch, …)`, │
 * │ que ninguém quer reimplementar. Nenhuma cor literal existe neste arquivo, │
 * │ e não por disciplina: por construção.                                     │
 * └────────────────────────────────────────────────────────────────────────────┘
 *
 * ┌─ MATIZ VEM DA ARTE, VALOR VEM DA MARCA ───────────────────────────────────┐
 * │ Pegar a cor dominante de uma capa e pintar a lombada com ela é o caminho  │
 * │ óbvio e está errado: pinturas têm dominantes claras, e uma lombada bege   │
 * │ de luminância 0.65 numa interface escura não lê como livro, lê como       │
 * │ vazamento de CSS.                                                         │
 * │                                                                            │
 * │ Então só o MATIZ atravessa. A saturação entra amortecida e a luminância   │
 * │ é derivada do `--background` de quem instalou: marca escura → livro       │
 * │ escuro, marca clara → livro claro. O objeto pertence à sua arte e         │
 * │ continua pertencendo à tela.                                              │
 * └────────────────────────────────────────────────────────────────────────────┘
 */

import { coverLook, mix } from "@/lib/cover-look";

export type Rgb = { r: number; g: number; b: number };
export type Hsl = { h: number; s: number; l: number };

/* ── O resolvedor ───────────────────────────────────────────────────────── */

/**
 * Qualquer expressão de cor do CSS → rgb, resolvida pelo navegador.
 *
 * O elemento fica FORA do fluxo e é removido no mesmo tique. `getComputedStyle`
 * força layout, então isto é caro num laço — e é por isso que só roda uma vez
 * por livro, na montagem, nunca por quadro.
 *
 * Devolve `null` fora do navegador e quando o token não existe: quem chama
 * decide o que fazer, e a decisão nunca é "usa este hex aqui".
 */
export function resolveRgb(css: string): Rgb | null {
  if (typeof document === "undefined") return null;
  const probe = document.createElement("span");
  probe.style.cssText = "position:absolute;visibility:hidden;pointer-events:none";
  probe.style.color = css;
  document.body.appendChild(probe);
  const painted = getComputedStyle(probe).color;
  probe.remove();
  const m = painted.match(/-?[\d.]+/g);
  if (!m || m.length < 3) return null;
  return { r: +m[0], g: +m[1], b: +m[2] };
}

/** Token do documento, ou `''` se ele não existir. */
export function token(name: string): string {
  if (typeof document === "undefined") return "";
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
}

/* ── Conversão ──────────────────────────────────────────────────────────── */

export function rgbToHsl({ r, g, b }: Rgb): Hsl {
  const rr = r / 255;
  const gg = g / 255;
  const bb = b / 255;
  const max = Math.max(rr, gg, bb);
  const min = Math.min(rr, gg, bb);
  const l = (max + min) / 2;
  if (max === min) return { h: 0, s: 0, l };
  const d = max - min;
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  const h =
    max === rr
      ? ((gg - bb) / d + (gg < bb ? 6 : 0)) / 6
      : max === gg
        ? ((bb - rr) / d + 2) / 6
        : ((rr - gg) / d + 4) / 6;
  return { h, s, l };
}

function channel(p: number, q: number, t: number): number {
  let tt = t;
  if (tt < 0) tt += 1;
  if (tt > 1) tt -= 1;
  if (tt < 1 / 6) return p + (q - p) * 6 * tt;
  if (tt < 1 / 2) return q;
  if (tt < 2 / 3) return p + (q - p) * (2 / 3 - tt) * 6;
  return p;
}

/** Sempre `rgb(…)`, nunca hex — o portão de cor do registry lê o CÓDIGO. */
export function hslToCss({ h, s, l }: Hsl): string {
  const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
  const p = 2 * l - q;
  const to = (t: number) => Math.round((s === 0 ? l : channel(p, q, t)) * 255);
  return `rgb(${to(h + 1 / 3)}, ${to(h)}, ${to(h - 1 / 3)})`;
}

export const rgbToCss = ({ r, g, b }: Rgb) => `rgb(${r}, ${g}, ${b})`;

/* ── A régua, derivada do --background ──────────────────────────────────── */

/**
 * Degraus de luminância a partir da superfície da marca, e o SINAL que decide
 * pra que lado eles crescem.
 *
 * Numa marca escura o livro tem que ser mais claro que a página pra ter
 * silhueta; numa marca clara, mais escuro. Um único `sign` resolve os dois
 * casos e é a razão de a peça não precisar de uma variante "dark".
 *
 * O papel dá um salto grande de propósito: o bloco de páginas é o único
 * material do objeto que não é a capa, e se ele ficar perto do tom do cartão o
 * livro vira um bloco só.
 */
const STEP = { spine: 0.15, dark: 0.035, board: 0.09, back: 0.055, paper: 0.72 };

/** Nem branco estourado nem preto chapado: os dois matam o degrau da praça. */
const clampL = (l: number) => Math.min(0.94, Math.max(0.05, l));

/** Teto de saturação. Livro tingido, não livro pintado. */
const SAT_CEILING = 0.34;

export type BookPalette = {
  /** Topo da lombada e da contracapa. */
  cover: string;
  /** Pé da lombada, e o par escuro de todo gradiente. */
  coverDark: string;
  /** Cartão da capa — o degrau que aparece na praça e na quina. */
  board: string;
  /** Fundo da contracapa. */
  back: string;
  /** Corte do miolo. */
  paper: string;
  /** Fundo do estúdio virtual. Não é o fundo da PÁGINA (o canvas é
   *  transparente): é o que o ambiente reflete na capa. */
  studio: string;
};

/**
 * A palheta inteira, a partir da semente do item e — se houver — do matiz da
 * arte da capa.
 *
 * Sem arte, o matiz vem da MESMA rampa que o `cover-art` usa pra desenhar a
 * capa 2D do mesmo item. Não é economia: é o que faz o livro e o card do
 * catálogo serem reconhecíveis como a mesma coisa.
 */
export function bookPalette(seed: string, artColor?: string | null): BookPalette {
  const look = coverLook(seed);

  const surface = resolveRgb("var(--background)");
  const lBg = surface ? rgbToHsl(surface).l : 0.05;
  const sign = lBg < 0.5 ? 1 : -1;
  const at = (step: number) => clampL(lBg + sign * step);

  /* O matiz: da arte quando ela existe, senão da rampa tonal da marca. */
  const source = resolveRgb(artColor || mix(look.light));
  const hsl = source ? rgbToHsl(source) : { h: 0, s: 0, l: 0.5 };
  const h = hsl.h;
  const s = Math.min(hsl.s, SAT_CEILING);

  return {
    cover: hslToCss({ h, s, l: at(STEP.spine) }),
    coverDark: hslToCss({ h, s: s * 0.85, l: at(STEP.dark) }),
    board: hslToCss({ h, s: s * 0.7, l: at(STEP.board) }),
    back: hslToCss({ h, s: s * 0.8, l: at(STEP.back) }),
    /* Papel quase neutro: um creme saturado puxaria cor pra dentro de um
       produto que pode ter decidido não ter cor. */
    paper: hslToCss({ h, s: s * 0.12, l: at(STEP.paper) }),
    studio: surface ? rgbToCss(surface) : hslToCss({ h: 0, s: 0, l: 0.06 }),
  };
}

/* ── Aspereza ───────────────────────────────────────────────────────────── */

/** Alto = pano e papel-cartão, não plástico. O erro clássico de render de livro
 *  é deixar isto baixo e o objeto virar brinquedo lustroso. */
export const ROUGH_COVER = 0.82;
export const ROUGH_PAPER = 0.95;

/* ── O matiz da arte ────────────────────────────────────────────────────── */

/** Grade de amostragem. Pequena de propósito: a média de uma pintura não muda
 *  entre 32×48 e 800×1200, e a leitura fica em microssegundos. */
const GRID_W = 32;
const GRID_H = 48;

/**
 * A cor de caráter de uma imagem, medida da própria textura já carregada.
 *
 * Existe pra que um item cadastrado amanhã já saia com a lombada na cor da arte,
 * sem ninguém rodar nada. Uma palheta curada por gente continua ganhando quando
 * existe (é o parâmetro `artColor`) — ela sabe o que é ASSUNTO e o que é fundo,
 * e isto aqui não sabe. Isto é o piso, não o teto.
 *
 * A média é CIRCULAR: matiz é ângulo, e a média aritmética de 350° e 10° dá
 * 180° — ciano, uma cor que não existe em nenhum dos dois pixels. Somar vetores
 * unitários e tirar o `atan2` no fim é o único jeito que respeita a roda.
 *
 * O peso é `saturação × proximidade do meio-tom`: pixel cinza não tem matiz pra
 * opinar, e branco estourado ou preto de sombra também não.
 */
export function characterColor(img: CanvasImageSource): string | null {
  try {
    const c = document.createElement("canvas");
    c.width = GRID_W;
    c.height = GRID_H;
    const ctx = c.getContext("2d", { willReadFrequently: true });
    if (!ctx) return null;
    ctx.drawImage(img, 0, 0, GRID_W, GRID_H);
    const { data } = ctx.getImageData(0, 0, GRID_W, GRID_H);

    let x = 0;
    let y = 0;
    let sumS = 0;
    let weight = 0;

    for (let i = 0; i < data.length; i += 4) {
      if (data[i + 3] < 128) continue;
      const { h, s, l } = rgbToHsl({ r: data[i], g: data[i + 1], b: data[i + 2] });
      const w = s * Math.max(0, 1 - Math.abs(l - 0.5) * 1.6);
      if (w <= 0) continue;
      const a = h * Math.PI * 2;
      x += Math.cos(a) * w;
      y += Math.sin(a) * w;
      sumS += s * w;
      weight += w;
    }

    /* Arte acromática (uma foto em preto e branco, um diagrama): não há matiz
       pra colher, e inventar um seria pior que herdar o tom da marca. */
    if (weight < 1e-6) return null;

    const h = (Math.atan2(y, x) / (Math.PI * 2) + 1) % 1;
    return hslToCss({ h, s: Math.min(1, sumS / weight), l: 0.5 });
  } catch {
    /* `getImageData` numa textura de outra origem sem CORS joga SecurityError.
       Livro sem cor de lombada é muito melhor que livro que não renderiza. */
    return null;
  }
}

/**
 * As faces que o item não fornece, pintadas em `<canvas>`.
 *
 * O item entrega UMA imagem: a capa de frente. Lombada, contracapa e corte do
 * miolo saem daqui, derivados da mesma semente e da mesma palheta. Isso não é
 * economia de esforço: é o que faz o mesmo item ser o mesmo objeto em qualquer
 * render, e o que permite cadastrar produto sem virar trabalho de arte.
 *
 * Zero byte de rede. A alternativa — três imagens por item num bucket —
 * significaria que trocar a paleta da marca deixaria o acervo inteiro com a cor
 * velha.
 */

import * as THREE from "three";

import { coverLook, monogram, type CoverLook } from "@/lib/cover-look";
import { resolveRgb, token, type BookPalette } from "@/lib/book-material";
import type { BookDimensions } from "@/lib/book-geometry";

/** Resolução das faces de texto. 1024 na altura é o que segura o título da
 *  lombada legível num herói sem serrilhar; acima disso é VRAM à toa. */
const TEX_H = 1024;

type Ctx = CanvasRenderingContext2D;

function surface(w: number, h: number): [HTMLCanvasElement, Ctx] {
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  return [c, c.getContext("2d")!];
}

/**
 * A tinta do texto, com alfa, saída do token — nunca escrita à mão.
 *
 * Canvas 2D não enxerga `var()` nem `color-mix()`: não há elemento, não há
 * cascata. Sem esta ponte, toda face pintada aqui teria a cor em canais crus, e
 * trocar o tema deixaria a lombada com a cor velha, em silêncio.
 */
function ink(pct: number): string {
  const fg = resolveRgb("var(--foreground)");
  const base = fg ? `${fg.r}, ${fg.g}, ${fg.b}` : "128, 128, 128";
  return `rgba(${base}, ${pct / 100})`;
}

/**
 * O nome da família que o pipeline de fonte gerou, lido do token.
 *
 * Hardcodar `'Inter'` aqui funcionaria em dev e falharia em produção: um
 * `next/font` publica a fonte com nome hasheado e o nome humano simplesmente
 * não existe no documento. Canvas não avisa — cai no fallback em silêncio e a
 * lombada sai com outra letra.
 */
function family(name: "--font-sans" | "--font-display"): string {
  return token(name) || "sans-serif";
}

function texture(canvas: HTMLCanvasElement): THREE.CanvasTexture {
  const t = new THREE.CanvasTexture(canvas);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 8;
  return t;
}

/** Encolhe o corpo até caber em UMA linha. É o caso da lombada, que não tem
 *  segunda linha pra oferecer: título cortado com reticências ali seria pior
 *  que título pequeno, porque a lombada É o nome do objeto. */
function fitOneLine(ctx: Ctx, text: string, limit: number, max: number, fam: string): number {
  let px = max;
  while (px > 10) {
    ctx.font = `700 ${px}px ${fam}`;
    if (ctx.measureText(text).width <= limit) break;
    px -= 2;
  }
  return px;
}

function wrap(ctx: Ctx, text: string, width: number): string[] {
  const lines: string[] = [];
  let line = "";
  for (const word of text.split(/\s+/)) {
    const attempt = line ? `${line} ${word}` : word;
    if (ctx.measureText(attempt).width > width && line) {
      lines.push(line);
      line = word;
    } else line = attempt;
  }
  if (line) lines.push(line);
  return lines;
}

/**
 * O maior corpo em que o título cabe em `maxLines` — a régua de CAPA, que é
 * outra coisa da régua de lombada.
 *
 * Usar `fitOneLine` aqui foi um defeito real: ela encolhe até caber numa linha,
 * e um título de cinco palavras só cabe numa linha em corpo minúsculo. A capa
 * saía ilegível ao lado das que têm arte, e a degradação — que existe pra o
 * item sem arte continuar tendo cara — virava a prova de que ele não tem.
 *
 * A ordem certa é a do tipógrafo: escolhe o corpo, QUEBRA, e só encolhe se
 * passar do número de linhas que a página aguenta. Uma palavra sozinha mais
 * larga que a coluna também derruba o corpo, e por isso a maior linha entra na
 * condição.
 */
function fitBlock(
  ctx: Ctx,
  text: string,
  width: number,
  max: number,
  maxLines: number,
  fam: string,
): { px: number; lines: string[] } {
  let px = max;
  let lines = [""];
  while (px > 12) {
    ctx.font = `800 ${px}px ${fam}`;
    lines = wrap(ctx, text, width);
    const widest = Math.max(...lines.map((l) => ctx.measureText(l).width));
    if (lines.length <= maxLines && widest <= width) break;
    px -= 2;
  }
  return { px, lines };
}

/* ── Lombada ────────────────────────────────────────────────────────────── */

/**
 * A face que justifica o 3D existir.
 *
 * Vai numa meia-cilíndrica, então a UV corre em volta da curva (u = largura da
 * lombada) e ao longo da altura (v). O texto roda 90° pra correr no v: livro
 * ocidental lê de cima pra baixo, com a cabeça inclinada pra direita.
 *
 * A LARGURA da textura é o ARCO, não a largura da capa. Foi `width / height`
 * (0.68) e o certo é `π·thickness/2 / height` — num livro grosso, 0.27. Assim a
 * textura saía duas vezes e meia mais larga do que a superfície onde pousa, e a
 * curva espremia tudo: o título ficava alto e fino, como letra esticada na
 * vertical. É o erro que mais denuncia mapeamento em superfície curva, porque o
 * olho conhece a proporção da letra e vê a distorção sem saber nomeá-la.
 *
 * As duas sombras nas pontas do u são a CHARNEIRA — o vinco onde a capa dobra.
 * Sem elas a curva lê como tubo colado no livro; com elas, como lombada.
 */
export function paintSpine(title: string, p: BookPalette, d: BookDimensions) {
  const arc = (Math.PI * d.thickness) / 2;
  /* Piso de 40px é só resolução: numa lombada fina o texto já é minúsculo, e
     forçar a largura acima da razão real traria a distorção de volta. */
  const W = Math.max(40, Math.round((arc / d.height) * TEX_H));
  const [canvas, ctx] = surface(W, TEX_H);

  const g = ctx.createLinearGradient(0, 0, 0, TEX_H);
  g.addColorStop(0, p.cover);
  g.addColorStop(1, p.coverDark);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, TEX_H);

  const hinge = ctx.createLinearGradient(0, 0, W, 0);
  hinge.addColorStop(0, "rgba(0,0,0,0.55)");
  hinge.addColorStop(0.13, "rgba(0,0,0,0)");
  hinge.addColorStop(0.87, "rgba(0,0,0,0)");
  hinge.addColorStop(1, "rgba(0,0,0,0.55)");
  ctx.fillStyle = hinge;
  ctx.fillRect(0, 0, W, TEX_H);

  const margin = W * 0.22;
  ctx.fillStyle = ink(22);
  ctx.fillRect(margin, TEX_H * 0.055, W - margin * 2, 2);
  ctx.fillRect(margin, TEX_H * 0.945, W - margin * 2, 2);

  ctx.save();
  ctx.translate(W / 2, TEX_H * 0.11);
  ctx.rotate(Math.PI / 2);
  const fam = family("--font-sans");
  const px = fitOneLine(ctx, title, TEX_H * 0.7, W * 0.46, fam);
  ctx.font = `700 ${px}px ${fam}`;
  ctx.fillStyle = ink(92);
  ctx.textAlign = "left";
  ctx.textBaseline = "middle";
  ctx.fillText(title, 0, 0);
  ctx.restore();

  /* Monograma no pé, onde numa estante real fica o selo da editora. */
  ctx.save();
  ctx.translate(W / 2, TEX_H * 0.9);
  ctx.rotate(Math.PI / 2);
  ctx.font = `400 ${Math.round(W * 0.3)}px ${family("--font-display")}`;
  ctx.fillStyle = ink(55);
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(monogram(title), 0, 0);
  ctx.restore();

  return texture(canvas);
}

/* ── Contracapa ─────────────────────────────────────────────────────────── */

/** Nunca fica de frente — o curso do hover para antes. Existe pra que a borda
 *  que se vê de três-quartos não seja um retângulo chapado. */
export function paintBack(p: BookPalette, ratio: number, mark?: string) {
  const W = Math.round(TEX_H * ratio);
  const [canvas, ctx] = surface(W, TEX_H);

  const g = ctx.createLinearGradient(0, 0, W, TEX_H);
  g.addColorStop(0, p.back);
  g.addColorStop(1, p.coverDark);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, TEX_H);

  ctx.fillStyle = ink(16);
  ctx.fillRect(W * 0.12, TEX_H * 0.86, W * 0.16, 2);

  if (mark) {
    ctx.font = `400 ${Math.round(W * 0.05)}px ${family("--font-display")}`;
    ctx.fillStyle = ink(40);
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
    ctx.fillText(mark, W * 0.12, TEX_H * 0.91);
  }

  return texture(canvas);
}

/* ── Corte do miolo ─────────────────────────────────────────────────────── */

/**
 * Uma textura por PALHETA, memoizada — é a mesma folha de papel em todo livro
 * de uma mesma marca, e refazê-la por item seria VRAM repetida.
 *
 * As listras não são regulares: passo constante bate com a grade de pixels e
 * produz moiré quando o livro gira, que é o artefato que mais denuncia render
 * barato. A variação vem de um seno, não de `Math.random` — determinismo aqui é
 * a diferença entre "renderizar duas vezes dá o mesmo resultado" e não dar.
 */
const blockCache = new Map<string, THREE.CanvasTexture>();

export function paintBlock(p: BookPalette): THREE.CanvasTexture {
  const cached = blockCache.get(p.paper);
  if (cached) return cached;

  const N = 1024;
  const [canvas, ctx] = surface(N, 64);

  ctx.fillStyle = p.paper;
  ctx.fillRect(0, 0, N, 64);

  for (let i = 0; i < 260; i++) {
    const x = (i / 260) * N + Math.sin(i * 2.399) * 1.6;
    const a = 0.06 + (Math.sin(i * 1.117) + 1) * 0.05;
    ctx.fillStyle = `rgba(0,0,0,${a.toFixed(3)})`;
    ctx.fillRect(x, 0, 1.2, 64);
  }

  /* Escurecimento nas duas pontas: o corte encosta nos cartões e ali entra
     menos luz. É o que impede o bloco de páginas de virar barra clara chapada. */
  const g = ctx.createLinearGradient(0, 0, N, 0);
  g.addColorStop(0, "rgba(0,0,0,0.42)");
  g.addColorStop(0.1, "rgba(0,0,0,0)");
  g.addColorStop(0.9, "rgba(0,0,0,0)");
  g.addColorStop(1, "rgba(0,0,0,0.42)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, N, 64);

  const t = texture(canvas);
  blockCache.set(p.paper, t);
  return t;
}

/* ── Capa de frente, quando não há arte ─────────────────────────────────── */

/**
 * Degradação honesta: sem arte o livro não vira caixa cinza nem imagem gerada —
 * vira a mesma capa desenhada que o `cover-art` mostra na prateleira, agora com
 * espessura. Mesmo hash, então o item é reconhecível nas duas superfícies.
 */
export function paintCover(title: string, look: CoverLook, p: BookPalette, ratio: number) {
  const W = Math.round(TEX_H * ratio);
  const [canvas, ctx] = surface(W, TEX_H);

  const rad = (look.angle * Math.PI) / 180;
  const g = ctx.createLinearGradient(0, 0, Math.cos(rad) * W, Math.sin(rad) * TEX_H);
  g.addColorStop(0, p.cover);
  g.addColorStop(1, p.coverDark);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, TEX_H);

  const m = W * 0.11;
  const base = look.titleOnTop ? TEX_H * 0.16 : TEX_H * 0.82;

  ctx.fillStyle = ink(28);
  ctx.fillRect(m, base - TEX_H * 0.055, W * 0.14, 2);

  const fam = family("--font-sans");
  /* Teto de 4 linhas: acima disso o título vira parágrafo e a capa vira
     folheto. O corpo de partida é generoso — capa não é lombada. */
  const { px, lines } = fitBlock(ctx, title, W - m * 2, W * 0.17, 4, fam);
  ctx.font = `800 ${px}px ${fam}`;
  ctx.fillStyle = ink(95);
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";

  /* Composição de BASE cresce pra cima e a de topo pra baixo. Sem isso, um
     título de quatro linhas ancorado no pé sangrava pra fora do cartão. */
  const leading = px * 1.08;
  const top = look.titleOnTop ? base : base - (lines.length - 1) * leading;
  lines.forEach((l, i) => ctx.fillText(l, m, top + i * leading));

  return texture(canvas);
}

/** Tudo que o livro precisa, num lugar só. */
export function bookFaces(
  seed: string,
  title: string,
  d: BookDimensions,
  palette: BookPalette,
  mark?: string,
) {
  const look = coverLook(seed);
  const ratio = d.width / d.height;
  return {
    spine: paintSpine(title, palette, d),
    back: paintBack(palette, ratio, mark),
    cover: paintCover(title, look, palette, ratio),
    block: paintBlock(palette),
  };
}

"use client";

/**
 * O palco: canvas, câmera, luz e a malha. Carregado sob demanda pelo
 * `book-3d` — nunca importe este arquivo direto, ou os ~180 KB de WebGL entram
 * no bundle de quem só queria mostrar um card.
 *
 * ┌─ POR QUE A MALHA NÃO É UMA CAIXA COM TEXTURA ─────────────────────────────┐
 * │ Caixa com a arte colada é o render de livro que todo mundo faz e que      │
 * │ ninguém acredita. Faltam duas coisas, e são as duas que o olho procura:   │
 * │                                                                            │
 * │   PRAÇA     a capa sobra além do bloco de páginas nas três bordas livres. │
 * │             É a sombra fina em volta do corte que diz "isso abre".        │
 * │   CHARNEIRA a lombada é uma meia-cilíndrica de verdade, com o vinco onde  │
 * │             a capa dobra. Lombada pintada num plano lê como adesivo.      │
 * │                                                                            │
 * │ Por isso são quatro peças (dois cartões + lombada + miolo) e não uma:     │
 * │ nenhuma textura produz um degrau que responde à luz quando o objeto gira. │
 * └────────────────────────────────────────────────────────────────────────────┘
 *
 * Nenhum asset baixado: sem GLB, sem HDR de CDN. Modelo de banco público seria
 * pior em quatro frentes — UV desconhecida (refazer o unwrap é o trabalho que o
 * modelo deveria evitar), proporção travada (espessura aqui é parâmetro),
 * 300 KB–2 MB de rede, e passivo de atribuição numa superfície comercial.
 */

import * as React from "react";
import * as THREE from "three";
import { Canvas, useFrame, useLoader, useThree } from "@react-three/fiber";
import { Environment, Lightformer } from "@react-three/drei";

import {
  BOARD,
  CAMERA,
  REST,
  SQUARE,
  STIFFNESS,
  bookDimensions,
  damp,
  tilt,
} from "@/lib/book-geometry";
import {
  ROUGH_COVER,
  ROUGH_PAPER,
  bookPalette,
  characterColor,
  resolveRgb,
  rgbToCss,
  type BookPalette,
} from "@/lib/book-material";
import { bookFaces } from "@/lib/book-faces";

/** O que o ponteiro está pedindo. Ref e não estado: mexer nisso 60× por segundo
 *  por `setState` re-renderiza a árvore React inteira a cada quadro. */
export type PointerTarget = { px: number; py: number; active: boolean };

export interface BookStageProps {
  /** Chave ESTÁVEL: slug > id > título. Título editado mudaria o objeto. */
  seed: string;
  title: string;
  /** A capa. Sem ela, o livro sai com a capa desenhada — nunca caixa cinza. */
  art?: string | null;
  /** Manda na espessura. Sem número, usa o livro de estante médio. */
  pages?: number | null;
  /**
   * Cor curada da arte, se houver. Ganha da amostragem automática — uma pessoa
   * (ou um extrator com noção de papel) sabe que o ocre da pedra é o assunto e
   * o céu é o fundo; uma média não sabe.
   */
  artColor?: string | null;
  /** Marca d'água na contracapa. Uma linha curta, tipo o selo da editora. */
  mark?: string;
  /** Chamado no primeiro quadro em que o livro existe POR INTEIRO. */
  onReady?: () => void;
}

type Shared = Pick<BookStageProps, "seed" | "title" | "pages" | "artColor" | "mark" | "onReady"> & {
  /**
   * Tipo ESTRUTURAL, e não `React.RefObject` / `MutableRefObject`.
   *
   * Os dois nomes mudaram de significado entre os types do React 18 e do 19:
   * no 18, `useRef` com valor inicial devolve `MutableRefObject`, que não é
   * atribuível a `RefObject`; no 19, `MutableRefObject` está depreciado. Um item
   * de registry é instalado em projetos das duas versões, então amarrar-se a
   * qualquer um dos dois nomes garante erro de tipo na metade dos consumidores.
   * `{ current: T }` é o que os dois têm em comum e sempre terão.
   */
  target: { current: PointerTarget };
  reduced: boolean;
};

/* ── O objeto ───────────────────────────────────────────────────────────── */

function Body({
  seed,
  title,
  pages,
  artColor,
  mark,
  onReady,
  target,
  reduced,
  cover,
  sampled,
}: Shared & { cover: THREE.Texture | null; sampled: string | null }) {
  const group = React.useRef<THREE.Group>(null);
  const announced = React.useRef(false);
  const { invalidate } = useThree();

  const d = React.useMemo(() => bookDimensions(pages), [pages]);
  const palette: BookPalette = React.useMemo(
    () => bookPalette(seed, artColor ?? sampled),
    [seed, artColor, sampled],
  );
  const faces = React.useMemo(
    () => bookFaces(seed, title, d, palette, mark),
    [seed, title, d, palette, mark],
  );

  /**
   * O miolo leva SEIS materiais porque o corte e a cabeça mostram o mesmo
   * empilhamento em direções diferentes: no corte as páginas correm na altura,
   * na cabeça correm na largura. Uma textura só nas duas faces deixa a cabeça
   * com listra atravessada — o tipo de erro que ninguém nomeia e todo mundo vê.
   */
  const blockMaterials = React.useMemo(() => {
    const edge = new THREE.MeshStandardMaterial({
      map: faces.block,
      roughness: ROUGH_PAPER,
      metalness: 0,
    });
    const turned = faces.block.clone();
    turned.needsUpdate = true;
    turned.center.set(0.5, 0.5);
    turned.rotation = Math.PI / 2;
    const head = new THREE.MeshStandardMaterial({
      map: turned,
      roughness: ROUGH_PAPER,
      metalness: 0,
    });
    /**
     * Faces que ficam atrás dos cartões e dentro da lombada. Escuras, e não cor
     * de papel — é a diferença entre um vazamento que lê como sombra e um que
     * lê como DEFEITO. Qualquer fresta de um pixel nesta montagem (e sempre há
     * uma, em algum ângulo) some se o que está atrás for escuro, e vira risco
     * claro se for papel.
     */
    const hidden = new THREE.MeshStandardMaterial({
      color: palette.coverDark,
      roughness: ROUGH_PAPER,
    });
    return [edge, hidden, head, head, hidden, hidden]; // +x −x +y −y +z −z
  }, [faces.block, palette.coverDark]);

  /** Lombada: [lateral, tampa de cima, tampa de baixo]. As tampas são o vazio
   *  entre a curva e o miolo — escuras, como o crescente que um livro de capa
   *  dura mostra na cabeça. */
  const spineMaterials = React.useMemo(() => {
    const side = new THREE.MeshStandardMaterial({
      map: faces.spine,
      roughness: ROUGH_COVER,
      metalness: 0,
    });
    const hollow = new THREE.MeshStandardMaterial({
      color: palette.coverDark,
      roughness: 1,
    });
    return [side, hollow, hollow];
  }, [faces.spine, palette.coverDark]);

  /**
   * Devolver a memória de vídeo ao desmontar.
   *
   * `three` não tem coleta de lixo: textura e material vivem na GPU até alguém
   * chamar `dispose()`. Numa página só isso nunca aparece, e é por isso que é
   * perigoso — o vazamento mora no CAMINHO que ainda não existe: prateleira que
   * pagina, filtro que remonta a lista, rota que entra e sai. Cada livro carrega
   * três canvases de 1024 de altura; algumas dezenas de remontagens e o
   * navegador começa a derrubar contexto WebGL, o que na tela lê como "os livros
   * sumiram" sem nenhum erro.
   *
   * Duas coisas NÃO se descartam, e é o detalhe que separa limpar de quebrar:
   * o corte do miolo é memoizado por palheta e serve todos os livros da marca,
   * e a textura da ARTE vem do cache de loader do fiber, que a reusa entre
   * montagens. Quem descarta essas é quem as guarda.
   */
  React.useEffect(() => {
    const own = [faces.spine, faces.back, faces.cover];
    const materials = [...blockMaterials, ...spineMaterials];
    return () => {
      own.forEach((t) => t.dispose());
      materials.forEach((m) => {
        if (m.map && m.map !== faces.block) m.map.dispose();
        m.dispose();
      });
    };
  }, [faces, blockMaterials, spineMaterials]);

  useFrame((_, dt) => {
    const g = group.current;
    if (!g) return;

    /* Primeiro quadro DESTE livro — não do canvas. Ver `onReady` em `book-3d`. */
    if (!announced.current) {
      announced.current = true;
      onReady?.();
    }

    const t = target.current;
    const goal = reduced || !t?.active ? REST : tilt(t.px, t.py);
    g.rotation.y = damp(g.rotation.y, goal.ry, STIFFNESS, dt);
    g.rotation.x = damp(g.rotation.x, goal.rx, STIFFNESS, dt);

    /**
     * `frameloop="demand"`: o quadro só acontece quando alguém pede. Enquanto o
     * livro ainda está indo pro destino, ele pede o próximo; parado, a GPU dorme
     * em 0 fps. Sem isto, uma página de catálogo queima bateria a 60 fps pra
     * desenhar um objeto que não se move.
     */
    const settled =
      Math.abs(g.rotation.y - goal.ry) < 1e-4 && Math.abs(g.rotation.x - goal.rx) < 1e-4;
    if (!settled) invalidate();
  });

  const half = d.thickness / 2;
  const lift = 0.0015; // folga da arte sobre o cartão; evita z-fighting

  return (
    <group ref={group} rotation={[REST.rx, REST.ry, 0]}>
      {/* CARTÃO DA FRENTE.
          Caixa reta, e não uma caixa com canto arredondado. O bisel parecia
          refinamento e era defeito: ele curva TODAS as arestas, inclusive a que
          encosta na lombada, e ali abria uma fresta por onde o miolo claro
          vazava — uma linha vertical entre a lombada e a capa, do topo ao pé.
          Aresta de cartão de livro é reta mesmo; o único arredondamento honesto
          neste objeto é a lombada, e essa é geometria de verdade. */}
      <mesh position={[0, 0, half - BOARD / 2]}>
        <boxGeometry args={[d.width, d.height, BOARD]} />
        <meshStandardMaterial color={palette.board} roughness={ROUGH_COVER} />
      </mesh>

      {/* A ARTE — a única coisa que o item precisa fornecer. */}
      <mesh position={[0, 0, half + lift]}>
        <planeGeometry args={[d.width, d.height]} />
        <meshStandardMaterial
          map={cover ?? faces.cover}
          roughness={ROUGH_COVER}
          metalness={0}
        />
      </mesh>

      {/* CARTÃO DE TRÁS + contracapa */}
      <mesh position={[0, 0, -half + BOARD / 2]}>
        <boxGeometry args={[d.width, d.height, BOARD]} />
        <meshStandardMaterial color={palette.board} roughness={ROUGH_COVER} />
      </mesh>
      <mesh position={[0, 0, -half - lift]} rotation={[0, Math.PI, 0]}>
        <planeGeometry args={[d.width, d.height]} />
        <meshStandardMaterial map={faces.back} roughness={ROUGH_COVER} metalness={0} />
      </mesh>

      {/* LOMBADA — meia-cilíndrica de raio E/2. Esse raio não é escolha: é o
          único que faz a curva encostar exatamente nas quinas dos dois cartões
          (−L/2, ±E/2). Qualquer outro abre fresta ou cria degrau. */}
      <mesh position={[-d.width / 2, 0, 0]} material={spineMaterials}>
        <cylinderGeometry args={[half, half, d.height, 48, 1, false, Math.PI, Math.PI]} />
      </mesh>

      {/* MIOLO — recuado pela praça nas três bordas livres, e entrando meia
          espessura pra DENTRO da cavidade da lombada. Um livro rebatido faz
          isso de verdade (o bloco acompanha a curva), e aqui resolve de quebra
          o vão que sobrava entre a face reta do miolo e a casca curva: em
          ângulo raso dava pra enxergar por dentro do livro. */}
      <mesh position={[-(half / 2 + SQUARE) / 2, 0, 0]} material={blockMaterials}>
        <boxGeometry args={[d.width - SQUARE + half / 2, d.height - SQUARE * 2, d.block]} />
      </mesh>
    </group>
  );
}

/* ── As duas naturezas de capa ──────────────────────────────────────────── */

/**
 * Livro COM arte. Suspende no `useLoader` até o byte chegar — por isso o
 * `<Suspense>` abaixo tem o livro SEM arte como reserva, e não um vazio.
 *
 * É aqui que a cor do objeto nasce quando ninguém curou uma: a imagem já está
 * decodificada na memória, então medir o matiz custa um `drawImage` de 32×48 e
 * nenhuma requisição.
 */
function WithArt({ art, ...shared }: Shared & { art: string }) {
  const tex = useLoader(THREE.TextureLoader, art);
  const sampled = React.useMemo(() => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.anisotropy = 8;
    return characterColor(tex.image as CanvasImageSource);
  }, [tex]);
  return <Body {...shared} cover={tex} sampled={sampled} />;
}

function WithoutArt(shared: Shared) {
  return <Body {...shared} cover={null} sampled={null} />;
}

/* ── O estúdio ──────────────────────────────────────────────────────────── */

/**
 * Luz sem baixar nada.
 *
 * `<Environment preset="studio" />` é o caminho óbvio e está errado aqui: o
 * preset busca um HDR num CDN de terceiro. Numa página de produto, quando o CDN
 * pisca o objeto fica preto. Com `<Lightformer>` o ambiente é RENDERIZADO na
 * hora, num cubo de 256, e o custo é uma vez na montagem.
 *
 * ┌─ O AMBIENTE NÃO SUBSTITUI A LUZ DIRETA ───────────────────────────────────┐
 * │ A primeira versão tinha só os lightformers, e na bancada o livro saiu     │
 * │ quase invisível: ambiente escuro sobre matéria escura não produz FORMA    │
 * │ nenhuma.                                                                  │
 * │                                                                            │
 * │ Ambiente dá o brilho da superfície — o pano da capa, o reflexo fraco na   │
 * │ curva da lombada. Quem desenha o volume é luz direcional, porque só ela   │
 * │ produz gradiente na face e sombra na quina. As duas coisas, não uma.      │
 * │                                                                            │
 * │ A chave vem de cima e da ESQUERDA: é o lado da lombada, e é o contraste   │
 * │ entre a curva iluminada e a capa em meia-luz que diz "isso tem lado".     │
 * │ Chave frontal achataria o objeto de volta ao retângulo.                   │
 * └────────────────────────────────────────────────────────────────────────────┘
 *
 * NÃO HÁ SOMBRA DE CONTATO, e isso foi medido, não esquecido. O
 * `<ContactShadows>` esteve aqui: sobre uma superfície escura, uma sombra preta
 * a 75% de opacidade move o pixel em menos de 15/255 — invisível. Custava um
 * alvo de render de 512 por quadro pra não aparecer em foto nenhuma. Numa marca
 * clara ela voltaria a valer, e por isso o comentário fica.
 */
function Studio({ backdrop }: { backdrop: string }) {
  return (
    <>
      {/* Piso de luz. Sem ele a contracapa e a sombra da praça viram buraco
          preto, e buraco preto lê como falha de textura. */}
      <ambientLight intensity={0.55} />
      <directionalLight position={[-2.6, 3.2, 3.4]} intensity={2.6} />
      {/* CONTRA — de trás e da direita, rasante. Acende a quina do corte e
          separa o livro do fundo, que costuma ser quase da mesma cor. */}
      <directionalLight position={[3.4, 1.2, -2.4]} intensity={1.5} />
      <directionalLight position={[1.2, -2.2, 1.6]} intensity={0.35} />

      <Environment resolution={256}>
        <color attach="background" args={[backdrop]} />
        <Lightformer form="rect" intensity={6} position={[0, 4, 2]} scale={[8, 5, 1]} target={[0, 0, 0]} />
        <Lightformer form="rect" intensity={4} position={[4, 1, -3]} scale={[5, 5, 1]} target={[0, 0, 0]} />
        <Lightformer form="rect" intensity={2} position={[-4, 0, 2]} scale={[5, 5, 1]} target={[0, 0, 0]} />
      </Environment>
    </>
  );
}

/* ── Movimento reduzido ─────────────────────────────────────────────────── */

/** Seis linhas em vez de uma dependência: o item já pesa three + fiber + drei,
 *  e puxar uma lib de animação inteira por um `matchMedia` seria caro. */
function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = React.useState(false);
  React.useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => setReduced(mq.matches);
    sync();
    mq.addEventListener("change", sync);
    return () => mq.removeEventListener("change", sync);
  }, []);
  return reduced;
}

/* ── O palco ────────────────────────────────────────────────────────────── */

export default function BookStage({ art, onReady, ...rest }: BookStageProps) {
  const target = React.useRef<PointerTarget>({ px: 0, py: 0, active: false });
  const nudge = React.useRef<(() => void) | null>(null);
  const reduced = usePrefersReducedMotion();

  /**
   * O ponteiro é lido no DIV, não na malha.
   *
   * Raycast no objeto só dispara com o cursor EM CIMA do livro, e o livro ocupa
   * menos de um terço da área. Na bancada isso lia como peça quebrada: o cursor
   * entrava na região, nada acontecia, e só perto do centro o objeto acordava.
   * A caixa inteira é a superfície de hover.
   */
  const move = React.useCallback((e: React.PointerEvent<HTMLDivElement>) => {
    const r = e.currentTarget.getBoundingClientRect();
    target.current = {
      px: ((e.clientX - r.left) / r.width) * 2 - 1,
      py: ((e.clientY - r.top) / r.height) * 2 - 1,
      active: true,
    };
    nudge.current?.();
  }, []);

  const release = React.useCallback(() => {
    target.current = { ...target.current, active: false };
    nudge.current?.();
  }, []);

  const shared = { ...rest, target, reduced, onReady };

  /**
   * O que o ambiente reflete na capa é a SUPERFÍCIE DA MARCA, não um cinza
   * escolhido aqui. Numa marca clara o reflexo tem que ser claro, senão o livro
   * parece recortado de outra foto. Resolvido uma vez: `getComputedStyle` força
   * layout e não pode entrar num laço de quadro.
   */
  const backdrop = React.useMemo(() => {
    const bg = resolveRgb("var(--background)");
    return bg ? rgbToCss(bg) : "rgb(16, 16, 20)";
  }, []);

  return (
    <div
      className="h-full w-full"
      onPointerMove={move}
      onPointerLeave={release}
      onPointerCancel={release}
      /* Toque não tem hover: o dedo arrasta e o livro segue, e ao soltar volta
         ao repouso. Sai de graça do Pointer Events — não há ramo de touch aqui. */
      onPointerUp={release}
    >
      <Canvas
        frameloop="demand"
        dpr={[1, 2]}
        gl={{ antialias: true, alpha: true }}
        camera={{ position: [...CAMERA.position], fov: CAMERA.fov }}
        onCreated={({ invalidate }) => {
          nudge.current = invalidate;
        }}
        style={{ touchAction: "pan-y" }}
      >
        <Studio backdrop={backdrop} />
        {/* A reserva do Suspense é o LIVRO INTEIRO com a capa desenhada, não um
            vazio nem um esqueleto. Enquanto a arte desce já há um objeto com
            lombada e espessura na tela, e a troca é só a face da frente. */}
        <React.Suspense fallback={<WithoutArt {...shared} />}>
          {art ? <WithArt art={art} {...shared} /> : <WithoutArt {...shared} />}
        </React.Suspense>
      </Canvas>
    </div>
  );
}

"use client";

/**
 * Book 3D — o item de catálogo como OBJETO.
 *
 * Capa dura com lombada curva, espessura vinda da contagem de páginas, praça
 * (a sobra do cartão além do bloco de páginas) e inclinação que segue o
 * ponteiro. A cor do objeto sai dos tokens da marca e do matiz da própria arte.
 *
 * ── Por que separado do palco ──────────────────────────────────────────────
 *
 * `three` + `fiber` + `drei` somam ~180 KB gz. Um `import` direto colaria isso
 * no bundle de QUALQUER rota que importasse este arquivo, inclusive as que só
 * mostram um card. Aqui o WebGL só desce quando o navegador chega na peça.
 *
 * `React.lazy` e não `next/dynamic` de propósito: o item roda em Vite, Remix e
 * Next igual, e `next/dynamic` só existe num deles.
 *
 * ── ONDE ISTO NÃO VAI ──────────────────────────────────────────────────────
 *
 * Num trilho de 20–40 cards. Quarenta contextos WebGL derrubam telefone, e o
 * navegador começa a descartar os mais antigos — o que na tela lê como "os
 * livros sumiram", sem erro nenhum. Pra prateleira longa, renderize uma vez e
 * sirva imagem; pra uma dobra de destaque com poucos itens, é aqui.
 */

import * as React from "react";

import { CoverArt } from "@/components/ui/cover-art";
import { cn } from "@/lib/utils";
import type { BookStageProps } from "@/components/ui/book-stage";

const BookStage = React.lazy(() => import("@/components/ui/book-stage"));

export interface Book3DProps extends BookStageProps {
  className?: string;
}

/**
 * O reserva é a capa 2D determinística do `cover-art`, na proporção do livro.
 *
 * Não é spinner e não é caixa cinza de propósito: enquanto o WebGL desce, e em
 * qualquer máquina onde ele não desça, a peça mostra a MESMA arte derivada da
 * mesma semente que o card do catálogo mostra. Quem olha nunca vê buraco, e
 * nunca vê duas identidades pro mesmo item.
 */
function Standby({ seed, title }: { seed: string; title: string }) {
  return (
    <div className="flex h-full w-full items-center justify-center">
      <div
        className="relative aspect-[0.68] h-[76%] overflow-hidden"
        /* Raio e transição vão em `style`, e não em classe arbitrária do
           Tailwind: `rounded-[var(--r-surface,4px)]` não gera regra nenhuma —
           a vírgula do fallback quebra o parser de valor arbitrário, e o portão
           `check:css-tokens` pegou as duas classes sem estilo. Falha silenciosa
           clássica: o className existe, o CSS não. */
        style={{ borderRadius: "var(--r-surface, 4px)" }}
      >
        <CoverArt title={title} seed={seed} family="book" titleless />
      </div>
    </div>
  );
}

export function Book3D({ className, ...stage }: Book3DProps) {
  const [ready, setReady] = React.useState(false);
  const announce = React.useCallback(() => setReady(true), []);
  const { seed, title, onReady } = stage;

  const handleReady = React.useCallback(() => {
    announce();
    onReady?.();
  }, [announce, onReady]);

  return (
    <div
      className={cn("relative aspect-[4/5] w-full", className)}
      role="img"
      aria-label={title}
    >
      {/**
       * O reserva fica ATRÁS e some no primeiro quadro do livro INTEIRO — não
       * do canvas.
       *
       * Duas armadilhas foram pagas aqui. A primeira: o canvas é transparente,
       * então enquanto as duas artes existem elas somam, e o objeto sai turvo
       * com a capa 2D aparecendo em volta da silhueta 3D. A segunda: avisar no
       * `onCreated` do canvas é cedo demais — ele nasce pronto muito antes de a
       * arte descer, então o reserva saía, o livro aparecia com a capa
       * DESENHADA e só então a pintura entrava. Duas trocas visíveis pra montar
       * uma peça só.
       *
       * `visibility` junto de `opacity` porque um canvas transparente sobre um
       * elemento invisível ainda paga composição — e some do leitor de tela,
       * que já ouve o `aria-label` do pai.
       */}
      <div
        className="absolute inset-0"
        aria-hidden
        style={{
          opacity: ready ? 0 : 1,
          visibility: ready ? "hidden" : "visible",
          transition: "opacity var(--dur-slow, 300ms) var(--ease-out, ease-out)",
        }}
      >
        <Standby seed={seed} title={title} />
      </div>

      <div className="absolute inset-0">
        <React.Suspense fallback={null}>
          <BookStage {...stage} onReady={handleReady} />
        </React.Suspense>
      </div>
    </div>
  );
}
